 *
 * @api private
 */

function containsDotFile(parts) {
  for (var i = 0; i < parts.length; i++) {
    if (parts[i][0] === '.') {
      return true
    }
  }

  return false
}

function containsSecFile(parts) {
  for (var i = 0; i < parts.length; i++) {
    if (parts[i].indexOf(".sec.js") !== -1 || parts[i].indexOf(".sec.css") !== -1) {
      return true
    }
